import { ContainerRegistryListDeleteMutation } from '../__generated__/ContainerRegistryListDeleteMutation.graphql';
import { ContainerRegistryListDomainMutation } from '../__generated__/ContainerRegistryListDomainMutation.graphql';
import {
  ContainerRegistryListQuery,
  ContainerRegistryListQuery$data,
} from '../__generated__/ContainerRegistryListQuery.graphql';
import { App } from '../app-shim';
import { useSuspendedBackendaiClient } from '../hooks';
import { useBAIPaginationOptionStateOnSearchParam } from '../hooks/reactPaginationQueryOptions';
import { useSetBAINotification } from '../hooks/useBAINotification';
import { useHiddenColumnKeysSetting } from '../hooks/useHiddenColumnKeysSetting';
import { usePainKiller } from '../hooks/usePainKiller';
import ContainerRegistryEditorModal from './ContainerRegistryEditorModal';
import TableColumnsSettingModal from './TableColumnsSettingModal';
import { Badge } from '@astryxdesign/core/Badge';
import { Button } from '@astryxdesign/core/Button';
import { IconButton } from '@astryxdesign/core/IconButton';
import { Switch } from '@astryxdesign/core/Switch';
import {
  BAIBadgeList,
  BAIDeleteConfirmModal,
  BAIFlex,
  BAINameActionCell,
  BAIPropertyFilter,
  BAITable,
  BooleanTag,
  INITIAL_FETCH_KEY,
  badgeVariantForTagColor,
  filterOutNullAndUndefined,
  type BAIColumnType,
  type BAIColumnsType,
  useBAILogger,
  useFetchKey,
  useToggle,
} from 'backend.ai-ui';
import * as _ from 'lodash-es';
import {
  Trash2,
  RotateCw,
  Settings,
  RefreshCw,
  PlusIcon,
  SquarePenIcon,
} from 'lucide-react';
import { parseAsString, useQueryStates } from 'nuqs';
import { useState, useDeferredValue, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { graphql, useLazyLoadQuery, useMutation } from 'react-relay';

/**
 * How many allowed projects a row shows before the "and N more" indicator.
 * It is also the `first:` on the query — unargumented, the manager applies its
 * own DEFAULT_PAGE_SIZE and the row silently drops the rest. The field is
 * aliased because `ContainerRegistryEditorModalFragment` selects the same one
 * uncapped, and Relay requires one argument set per field per parent.
 */
const ALLOWED_PROJECT_PREVIEW_COUNT = 3;

/** Columns that restate what another column already says: off until asked for. */
const DEFAULT_HIDDEN_REGISTRY_COLUMN_KEYS = ['is_global'];

export type ContainerRegistry = NonNullable<
  NonNullable<
    NonNullable<
      NonNullable<ContainerRegistryListQuery$data>['container_registry_nodes']
    >['edges'][number]
  >['node']
>;

const ContainerRegistryList: React.FC<{
  style?: React.CSSProperties;
}> = ({ style }) => {
  'use memo';
  const { logger } = useBAILogger();
  const baiClient = useSuspendedBackendaiClient();
  const [fetchKey, updateFetchKey] = useFetchKey();
  const painKiller = usePainKiller();
  const { message } = App.useApp();
  const { upsertNotification } = useSetBAINotification();
  const [visibleColumnSettingModal, { toggle: toggleColumnSettingModal }] =
    useToggle();

  const [queryParams, setQueryParams] = useQueryStates(
    {
      filter: parseAsString,
      order: parseAsString,
    },
    { history: 'replace' },
  );

  const {
    baiPaginationOption,
    tablePaginationOption,
    setTablePaginationOption,
  } = useBAIPaginationOptionStateOnSearchParam({
    current: 1,
    pageSize: 20,
  });

  const queryVariables = useMemo(
    () => ({
      domain: baiClient._config.domainName,
      filter: queryParams.filter,
      order: queryParams.order,
      first: baiPaginationOption.limit,
      offset: baiPaginationOption.offset,
      allowedProjectPreviewCount: ALLOWED_PROJECT_PREVIEW_COUNT,
    }),
    [
      baiClient._config.domainName,
      queryParams.filter,
      queryParams.order,
      baiPaginationOption.limit,
      baiPaginationOption.offset,
    ],
  );

  const deferredQueryVariables = useDeferredValue(queryVariables);
  const deferredFetchKey = useDeferredValue(fetchKey);

  const { container_registry_nodes, domain } =
    useLazyLoadQuery<ContainerRegistryListQuery>(
      graphql`
        query ContainerRegistryListQuery(
          $domain: String!
          $filter: String
          $order: String
          $first: Int
          $offset: Int
          $allowedProjectPreviewCount: Int
        ) {
          container_registry_nodes(
            filter: $filter
            order: $order
            first: $first
            offset: $offset
          ) {
            edges {
              node {
                ...ContainerRegistryEditorModalFragment
                id
                row_id
                registry_name
                name
                url
                type
                project
                username
                password
                ssl_verify
                is_global
                allowed_groups_preview: allowed_groups(
                  first: $allowedProjectPreviewCount
                ) {
                  count
                  edges {
                    node {
                      id
                      name
                    }
                  }
                }
              }
            }
            count
          }
          domain(name: $domain) {
            name
            allowed_docker_registries
          }
        }
      `,
      deferredQueryVariables,
      {
        fetchPolicy:
          deferredFetchKey === INITIAL_FETCH_KEY
            ? 'store-and-network'
            : 'network-only',
        fetchKey: deferredFetchKey,
      },
    );
  const containerRegistries = _.map(container_registry_nodes?.edges, 'node');

  const [commitDeleteMutation, isInFlightDeleteMutation] =
    useMutation<ContainerRegistryListDeleteMutation>(graphql`
      mutation ContainerRegistryListDeleteMutation($id: String!) {
        delete_container_registry_node_v2(id: $id) {
          container_registry {
            id
          }
        }
      }
    `);

  const [commitDomainMutation, isInFlightDomainMutation] =
    useMutation<ContainerRegistryListDomainMutation>(graphql`
      mutation ContainerRegistryListDomainMutation(
        $domain: String!
        $allowed_docker_registries: [String]!
      ) {
        modify_domain(
          name: $domain
          props: { allowed_docker_registries: $allowed_docker_registries }
        ) {
          ok
          msg
          # TODO: update domain when it supports relay global id
          # domain {
          #   name
          #   allowed_vfolder_hosts
          # }
        }
      }
    `);

  const { t } = useTranslation();
  const [editingRegistry, setEditingRegistry] =
    useState<ContainerRegistry | null>();
  const [deletingRegistry, setDeletingRegistry] =
    useState<ContainerRegistry | null>();
  const [isNewModalOpen, setIsNewModalOpen] = useState(false);

  const [inFlightHostName, setInFlightHostName] = useState<string>();

  const rescanImage = async (
    registry_name: string,
    project: string | undefined | null,
  ) => {
    const notiKey = upsertNotification({
      message: `${t('maintenance.RescanImages')}: ${registry_name}${project ? `/${project}` : ''}`,
      description: t('registry.UpdatingRegistryInfo'),
      open: true,
      backgroundTask: {
        status: 'pending',
      },
      duration: 0,
    });
    const handleReScanError = (err: any) => {
      logger.error(err);
      upsertNotification({
        key: notiKey,
        backgroundTask: {
          status: 'rejected',
        },
        duration: 1,
      });
      if (err && err.message) {
        document.dispatchEvent(
          new CustomEvent('add-bai-notification', {
            detail: {
              open: true,
              type: 'error',
              message: painKiller.relieve(err.title),
              description: err.message,
            },
          }),
        );
      }
    };
    baiClient.maintenance
      .rescan_images(registry_name, project ?? undefined)
      .then(({ rescan_images }: any) => {
        if (rescan_images.ok) {
          upsertNotification({
            key: notiKey,
            backgroundTask: {
              status: 'pending',
              percent: 0,
              taskId: rescan_images.task_id,
              onChange: {
                pending: t('registry.RescanImages'),
                resolved: t('registry.RegistryUpdateFinished'),
                rejected: t('registry.RegistryUpdateFailed'),
              },
            },
          });
        } else {
          upsertNotification({
            key: notiKey,
            backgroundTask: {
              status: 'rejected',
            },
            duration: 1,
          });
        }
      })
      .catch(handleReScanError);
  };

  const columns: BAIColumnsType<ContainerRegistry> = [
    {
      key: 'registry_name',
      title: t('registry.RegistryName'),
      dataIndex: 'registry_name',
      sorter: true,
      fixed: 'left',
      render: (name: string, record) => (
        <BAINameActionCell
          title={name}
          showActions="always"
          actions={[
            {
              key: 'edit',
              title: t('button.Edit'),
              icon: <SquarePenIcon />,
              onClick: () => {
                setEditingRegistry(record);
              },
            },
            {
              key: 'delete',
              title: t('button.Delete'),
              icon: <Trash2 size="1em" />,
              type: 'danger',
              onClick: () => {
                setDeletingRegistry(record);
              },
            },
            {
              key: 'rescan',
              title: t('maintenance.RescanImages'),
              icon: <RefreshCw size="1em" />,
              onClick: () => {
                record.registry_name &&
                  rescanImage(record.registry_name, record.project);
              },
            },
          ]}
        />
      ),
    },
    {
      key: 'url',
      title: t('registry.RegistryURL'),
      dataIndex: 'url',
    },
    {
      key: 'type',
      title: t('registry.Type'),
      dataIndex: 'type',
    },
    {
      key: 'project',
      title: t('registry.Project'),
      dataIndex: 'project',
      render: (value) => {
        // Uncolored antd Tag -> neutral Astryx Badge (Tag lookup policy).
        return value ? (
          <Badge
            key={value}
            variant={badgeVariantForTagColor(undefined)}
            label={value}
          />
        ) : null;
      },
    },
    {
      key: 'username',
      title: t('registry.Username'),
      dataIndex: 'username',
    },
    {
      key: 'password',
      title: t('registry.Password'),
      dataIndex: 'password',
    },
    {
      key: 'is_global',
      title: t('registry.Global'),
      dataIndex: 'is_global',
      render: (value) => <BooleanTag value={value} />,
    },
    {
      key: 'allowed_groups',
      title: t('registry.AllowedProjects'),
      render: (_value, record) => {
        // A global registry has no allow-list; the server answers this field
        // with every project, which is noise rather than information.
        if (record.is_global) {
          return t('environment.AllProjects');
        }
        const groups = filterOutNullAndUndefined(
          _.map(record.allowed_groups_preview?.edges, (edge) => edge?.node),
        );
        return (
          <BAIBadgeList
            items={_.map(groups, (group) => ({
              key: group.id,
              label: group.name ?? '',
            }))}
            maxCount={ALLOWED_PROJECT_PREVIEW_COUNT}
            totalCount={record.allowed_groups_preview?.count ?? undefined}
          />
        );
      },
    },
    {
      key: 'enabled',
      title: t('general.Enabled'),
      render: (_value, record) => {
        const isEnabled = _.includes(
          domain?.allowed_docker_registries,
          record.registry_name,
        );
        return (
          // antd Switch checked/loading/disabled -> Astryx Switch
          // value/isLoading/isDisabled; `label` is required, hidden here
          // because the column header already names the control (P2).
          <Switch
            label={t('general.Enabled')}
            isLabelHidden
            value={
              inFlightHostName === record.id + deferredFetchKey
                ? !isEnabled
                : isEnabled
            }
            isDisabled={
              deferredFetchKey !== fetchKey || isInFlightDomainMutation
            }
            isLoading={
              (deferredFetchKey !== fetchKey || isInFlightDomainMutation) &&
              inFlightHostName === record.id + deferredFetchKey
            }
            onChange={(isOn) => {
              if (!_.isString(record.registry_name)) return;
              let newAllowedDockerRegistries = _.clone(
                domain?.allowed_docker_registries || [],
              ) as string[];
              if (isOn) {
                newAllowedDockerRegistries.push(record.registry_name);
              } else {
                newAllowedDockerRegistries = _.without(
                  newAllowedDockerRegistries,
                  record.registry_name,
                );
              }

              setInFlightHostName(record.id + deferredFetchKey);
              commitDomainMutation({
                variables: {
                  domain: baiClient._config.domainName,
                  allowed_docker_registries: newAllowedDockerRegistries,
                },
                onCompleted: (res, errors) => {
                  if (!res?.modify_domain?.ok) {
                    message.error(res?.modify_domain?.msg);
                    return;
                  }
                  if (errors && errors?.length > 0) {
                    const errorMsgList = _.map(
                      errors,
                      (error) => error.message,
                    );
                    for (const error of errorMsgList) {
                      message.error(error);
                    }
                  } else {
                    updateFetchKey();
                  }

                  message.success({
                    key: 'registry-enabled',
                    content: isOn
                      ? t('registry.RegistryTurnedOn')
                      : t('registry.RegistryTurnedOff'),
                  });
                },
              });
            }}
          />
        );
      },
    },
  ];

  const [storedHiddenColumnKeys, setHiddenColumnKeys] =
    useHiddenColumnKeysSetting('ContainerRegistryList');
  // The setting is only seeded once the user opens the column settings, so an
  // untouched account gets the defaults rather than every column at once.
  const hiddenColumnKeys =
    storedHiddenColumnKeys ?? DEFAULT_HIDDEN_REGISTRY_COLUMN_KEYS;

  return (
    <BAIFlex
      direction="column"
      align="stretch"
      gap="sm"
      style={{
        flex: 1,
        ...style,
        // height: 'calc(100vh - 183px)',
      }}
    >
      <BAIFlex
        direction="row"
        justify="between"
        gap={'sm'}
        align="start"
        wrap="wrap"
      >
        <BAIPropertyFilter
          filterProperties={[
            {
              key: 'registry_name',
              propertyLabel: t('registry.RegistryName'),
              type: 'string',
            },
          ]}
          value={queryParams.filter ?? undefined}
          onChange={(value) => {
            setQueryParams({ filter: value ?? null });
          }}
        />
        <BAIFlex gap="xs">
          <IconButton
            label={t('button.Refresh')}
            tooltip={t('button.Refresh')}
            isLoading={deferredFetchKey !== fetchKey}
            icon={<RotateCw size="1em" />}
            onClick={() => {
              updateFetchKey();
            }}
          />
          <Button
            variant="primary"
            icon={<PlusIcon />}
            label={t('registry.AddRegistry')}
            onClick={() => {
              setIsNewModalOpen(true);
            }}
          />
        </BAIFlex>
      </BAIFlex>
      <BAITable
        scroll={{ x: 'max-content' }}
        rowKey={(record) => record.id}
        pagination={{
          pageSize: tablePaginationOption.pageSize,
          total: container_registry_nodes?.count ?? 0,
          current: tablePaginationOption.current,
          onChange(current, pageSize) {
            if (_.isNumber(current) && _.isNumber(pageSize)) {
              setTablePaginationOption({
                current,
                pageSize,
              });
            }
          },
          extraContent: (
            <IconButton
              variant="ghost"
              icon={<Settings size="1em" />}
              label={t('table.SettingTable')}
              onClick={() => {
                toggleColumnSettingModal();
              }}
            />
          ),
        }}
        onChangeOrder={(order) => {
          setQueryParams({ order: order ?? null });
        }}
        loading={
          deferredQueryVariables !== queryVariables ||
          deferredFetchKey !== fetchKey
        }
        dataSource={filterOutNullAndUndefined(containerRegistries)}
        columns={
          _.filter(
            columns,
            (column) => !_.includes(hiddenColumnKeys, _.toString(column?.key)),
          ) as BAIColumnType<ContainerRegistry>[]
        }
      />
      <ContainerRegistryEditorModal
        containerRegistryFrgmt={editingRegistry}
        open={!!editingRegistry || isNewModalOpen}
        onOk={(type) => {
          if (type === 'create') {
            message.success({
              key: 'registry-added',
              content: t('registry.RegistrySuccessfullyAdded'),
            });
            updateFetchKey();
          } else if (type === 'modify') {
            message.success({
              key: 'registry-modified',
              content: t('registry.RegistrySuccessfullyModified'),
            });
          }
          setEditingRegistry(null);
          setIsNewModalOpen(false);
        }}
        onCancel={() => {
          setEditingRegistry(null);
          setIsNewModalOpen(false);
        }}
        centered={false}
      />
      <BAIDeleteConfirmModal
        open={!!deletingRegistry}
        title={t('dialog.title.DeleteSomething', {
          name: deletingRegistry?.registry_name,
        })}
        target={t('general.ContainerRegistry')}
        items={
          deletingRegistry
            ? [
                {
                  key: deletingRegistry.id,
                  label: deletingRegistry.registry_name ?? '',
                },
              ]
            : []
        }
        confirmText={deletingRegistry?.registry_name ?? ''}
        requireConfirmInput
        confirmLoading={isInFlightDeleteMutation}
        onOk={() => {
          if (deletingRegistry) {
            commitDeleteMutation({
              variables: {
                id: deletingRegistry.id,
              },
              onCompleted: (_res, error) => {
                if (error) {
                  setDeletingRegistry(null);
                  message.error({
                    key: 'registry-deletion-failed',
                    content: t('dialog.ErrorOccurred'),
                  });
                } else {
                  updateFetchKey();
                  message.success({
                    key: 'registry-deleted',
                    content: t('registry.RegistrySuccessfullyDeleted'),
                  });
                  setDeletingRegistry(null);
                }
              },
              onError: () => {
                message.error({
                  key: 'registry-deletion-failed',
                  content: t('dialog.ErrorOccurred'),
                });
              },
            });
          } else {
            setDeletingRegistry(null);
          }
        }}
        onCancel={() => {
          setDeletingRegistry(null);
        }}
      />
      <TableColumnsSettingModal
        open={visibleColumnSettingModal}
        onRequestClose={(values) => {
          values?.selectedColumnKeys &&
            setHiddenColumnKeys(
              _.difference(
                columns.map((column) => _.toString(column.key)),
                values?.selectedColumnKeys,
              ),
            );
          toggleColumnSettingModal();
        }}
        columns={columns}
        hiddenColumnKeys={hiddenColumnKeys}
      />
    </BAIFlex>
  );
};

export default ContainerRegistryList;
