export type EnvironmentImage = NonNullableNodeOnEdges<
  ImageListQuery$data['image_nodes']
>;

const availableImageSorterKeys = [
  'registry',
  'architecture',
  'namespace',
  'base_image_name',
  'name',
  'tag',
  'status',
  'is_local',
  'accelerators',
] as const;
const availableImageSorterValues = [
  ...availableImageSorterKeys,
  ...availableImageSorterKeys.map((key) => `-${key}` as const),
] as const;
const isEnableSorter = (key: string) =>
  _.includes(availableImageSorterKeys, key);

/**
 * Columns that carry detail rather than identity: off until asked for.
 * `status` is in here because the list is live-only unless the user adds a
 * status condition, so the column would read ALIVE on every row by default.
 */
const DEFAULT_HIDDEN_IMAGE_COLUMN_KEYS = [
  'status',
  'type',
  'is_local',
  'aliases',
  'supported_accelerators',
];

/** Every `ImageStatus` the manager knows, i.e. "do not narrow by status". */
export const ALL_IMAGE_STATUSES = [
  'ALIVE',
  'DELETED',
  'PURGING',
  'PURGE_ERROR',
] as const;

// Values in the minilang are double-quoted and carry no escapes, so a quoted
// span can hold anything — `status` included. Blank them before matching.
const stripQuotedValues = (filter: string) => filter.replace(/"[^"]*"/g, '""');

const hasStatusCondition = (filter: string) =>
  /(?:^|[&|(])\s*status\s/.test(stripQuotedValues(filter));

/**
 * The `filter_by_statuses` argument a given queryfilter needs. A `status`
 * condition is ANDed with it, and its server default is `[ALIVE]`, so such a
 * condition can never match anything else unless the argument widens too.
 * `undefined` leaves the default alone — the list stays live-only.
 */
export const filterByStatusesFor = (filter: string) =>
  hasStatusCondition(filter) ? [...ALL_IMAGE_STATUSES] : undefined;

interface ImageListProps {
  /**
   * Explicit project prop contract (ADR-0001, FR-3415). The Environments page
   * owns the (URL-persisted) choice; this component never reads the ambient
   * current project.
   *
   * `null` is NOT an error state: the list then scopes to the whole DOMAIN
   * (`domain:<domainName>`) and the project becomes an optional filter that
   * narrows it. See ADR-0001 for why `domain:` and not `system:`.
   */
  project: ProjectContextOrNull;
  /**
   * Reports the project the user picked — or `null` when the filter is
   * cleared — in the in-list selector. The project narrows what this list
   * SHOWS, so the selector is a content-scoped control and lives in this
   * list's own filter row rather than in the page's card header
   * (`.claude/rules/use-bai-card.md`).
   */
  onChangeProject: (project: ProjectContextOrNull) => void;
  style?: React.CSSProperties;
}

const ImageList: React.FC<ImageListProps> = ({
  project,
  onChangeProject,
  style,
}) => {
  'use memo';

  const { t } = useTranslation();
  const baiClient = useSuspendedBackendaiClient();

  // `image_nodes(scope_id:)` is NON-NULL, so there is no "omit it" form — but
  // `ScopeField` accepts `<TYPE>:<ID>` for TYPE in system/domain/project/user
  // (manager `api/gql_legacy/fields.py`). With no project filter the list
  // therefore defaults to the caller's own DOMAIN: the widest scope this page
  // may legitimately show, and an exact match for a domain admin's authority
  // (`/admin/environment` is `access: 'admin'`). `system:` is deliberately NOT
  // used — the manager derives it from the caller's own project memberships
  // and raises `IndexError` for an admin who belongs to zero projects
  // (`models/image/row.py`). See ADR-0001.
  const scopeId = project
    ? `project:${project.id}`
    : `domain:${baiClient._config.domainName}`;

  const projectSelect = (
    <BAIFlex gap="xs" align="center" wrap="wrap">
      <Text color="secondary">{t('general.Project')}</Text>
      <Suspense fallback={<BAISkeleton variant="input" size="small" />}>
        <ProjectSelectForAdminPage
          data-testid="environment-project-select"
          domain={baiClient._config.domainName}
          value={project?.id ?? undefined}
          // An optional FILTER, not a required choice: clearing it puts the
          // list back on the domain-wide default. antd routes the clear
          // through `onChange` with no option, so an absent `projectInfo` IS
          // the "cleared" signal.
          allowClear
          placeholder={t('environment.AllProjects')}
          style={{ minWidth: 180 }}
          onSelectProject={(projectInfo) => {
            onChangeProject(
              projectInfo
                ? { id: projectInfo.projectId, name: projectInfo.projectName }
                : null,
            );
          }}
        />
      </Suspense>
    </BAIFlex>
  );

  return (
    <ImageListInScope
      scopeId={scopeId}
      projectSelect={projectSelect}
      style={style}
    />
  );
};

interface ImageListInScopeProps {
  /** `project:<id>` when the filter is active, `domain:<name>` otherwise. */
  scopeId: string;
  /** The project filter control, rendered inside the filter row. */
  projectSelect: React.ReactNode;
  style?: React.CSSProperties;
}

const ImageListInScope: React.FC<ImageListInScopeProps> = ({
  scopeId,
  projectSelect,
  style,
}) => {
  'use memo';

  const { t } = useTranslation();
  const [selectedRows, setSelectedRows] = useState<EnvironmentImage[]>([]);
  const [, { tagAlias }] = useBackendAIImageMetaData();
  const { token } = theme.useToken();
  const [managingApp, setManagingApp] = useState<EnvironmentImage | null>(null);
  const [managingResourceLimit, setManagingResourceLimit] =
    useState<EnvironmentImage | null>(null);
  const [isOpenInstallModal, setIsOpenInstallModal] = useState<boolean>(false);
  const [fetchKey, updateFetchKey] = useFetchKey();
  const [, startTransition] = useTransition();
  const [installingImages, setInstallingImages] = useState<string[]>([]);
  const { message } = App.useApp();
  const [imageFilter, setImageFilter] = useState('');
  const [visibleColumnSettingModal, { toggle: toggleColumnSettingModal }] =
    useToggle();
  const [isPendingRefreshTransition, startRefreshTransition] = useTransition();

  // Selected rows belong to one scope. Reset during render rather than
  // remounting on a `key`, which would discard the deferred scope transition
  // below (it renders the previous list while the new scope loads).
  const [selectedRowsScopeId, setSelectedRowsScopeId] = useState(scopeId);
  if (selectedRowsScopeId !== scopeId) {
    setSelectedRowsScopeId(scopeId);
    setSelectedRows([]);
  }

  const {
    baiPaginationOption,
    tablePaginationOption,
    setTablePaginationOption,
  } = useBAIPaginationOptionStateOnSearchParam({
    current: 1,
    pageSize: 20,
  });

  const [queryParams, setQueryParams] = useQueryStates(
    {
      order: parseAsStringLiteral(availableImageSorterValues),
    },
    { history: 'replace' },
  );

  const queryVariables: ImageListQuery$variables = {
    scopeId,
    offset: baiPaginationOption.offset,
    first: baiPaginationOption.first,
    filter: imageFilter || undefined,
    order: queryParams.order || undefined,
    filterByStatuses: filterByStatusesFor(imageFilter),
  };
  const deferredQueryVariables = useDeferredValue(queryVariables);
  const deferredFetchKey = useDeferredValue(fetchKey);

  const { image_nodes } = useLazyLoadQuery<ImageListQuery>(
    graphql`
      query ImageListQuery(
        $scopeId: ScopeField!
        $offset: Int
        $first: Int
        $filter: String
        $order: String
        $filterByStatuses: [ImageStatus]
      ) {
        image_nodes(
          scope_id: $scopeId
          offset: $offset
          first: $first
          filter: $filter
          order: $order
          filter_by_statuses: $filterByStatuses
        ) {
          edges @required(action: THROW) {
            node @required(action: THROW) {
              id @required(action: THROW)
              name @deprecatedSince(version: "24.12.0")
              tag
              registry
              architecture
              digest
              installed
              labels {
                key
                value
              }
              humanized_name
              resource_limits {
                key
                min
                max
              }
              namespace
              base_image_name
              tags {
                key
                value
              }
              version
              size_bytes
              is_local
              supported_accelerators
              status
              type
              aliases
              ...AliasedImageDoubleTagsFragment
              ...ManageImageResourceLimitModal_image
              ...ManageAppsModal_image
            }
          }
          count
        }
      }
    `,
    deferredQueryVariables,
    {
      fetchPolicy:
        deferredFetchKey === INITIAL_FETCH_KEY
          ? 'store-and-network'
          : 'network-only',
      fetchKey: deferredFetchKey,
    },
  );

  const imageData = filterOutNullAndUndefined(
    image_nodes?.edges?.map((edge) => edge?.node) ?? [],
  );

  const columns: Array<BAIColumnType<EnvironmentImage>> = filterOutEmpty([
    {
      title: t('environment.Status'),
      dataIndex: 'installed',
      key: 'installed',
      // antd `Tag color="gold"` -> Astryx Badge via the repo-global Tag
      // lookup (ticket 13 policy): gold -> yellow.
      render: (_text, row) => (
        <BAIFlex direction="row" gap="xxs" wrap="wrap">
          {row?.id && installingImages.includes(row.id) ? (
            <Badge
              variant={badgeVariantForTagColor('gold')}
              label={t('environment.Installing')}
            />
          ) : row?.installed ? (
            <Badge
              variant={badgeVariantForTagColor('gold')}
              label={t('environment.Installed')}
            />
          ) : null}
          {/* An installed private image cannot be picked in the session
              launcher, so surface the label here (FR-70). */}
          {isPrivateImage(row) ? (
            <Badge
              variant={badgeVariantForTagColor('red')}
              label={t('environment.Private')}
            />
          ) : null}
        </BAIFlex>
      ),
    },
    {
      title: t('environment.FullImagePath'),
      key: 'fullImagePath',
      // The record arrives as `render`'s SECOND argument — this column is
      // computed and has no `dataIndex`, so the first argument (the cell
      // value) is `undefined`. Reading the row off the first argument is an
      // rc-table quirk that `BAITable` does not reproduce; taking it
      // from the second is the Astryx/antd `(value, record, index)` contract.
      render: (_value, row) => (
        // The table cell is `white-space: nowrap; overflow: hidden`, so an
        // untruncated path is clipped rather than wrapped.
        <BAIText monospace copyable ellipsis={{ tooltip: true }}>
          {getImageFullName(row) || ''}
        </BAIText>
      ),
      // Computed (`getImageFullName`); `name` is the server column the path is
      // built from, so it is the closest ordering the backend colmap offers.
      sorter: isEnableSorter('name'),
      sortKey: 'name',
      width: token.screenXS,
    },
    {
      title: t('environment.Registry'),
      dataIndex: 'registry',
      key: 'registry',
      sorter: isEnableSorter('registry'),
    },
    {
      title: t('environment.Architecture'),
      dataIndex: 'architecture',
      key: 'architecture',
      sorter: isEnableSorter('architecture'),
    },
    {
      title: t('environment.Namespace'),
      key: 'namespace',
      dataIndex: 'namespace',
      sorter: isEnableSorter('namespace'),
    },
    {
      title: t('environment.BaseImageName'),
      key: 'base_image_name',
      dataIndex: 'base_image_name',
      sorter: isEnableSorter('base_image_name'),
      render: (text) => tagAlias(text),
    },
    {
      title: t('environment.Version'),
      key: 'version',
      dataIndex: 'version',
    },
    {
      title: t('environment.Tags'),
      key: 'tags',
      dataIndex: 'tags',
      // The backend orders by the raw `tag` column, not the parsed KV list.
      sorter: isEnableSorter('tag'),
      sortKey: 'tag',
      render: (_text, row) => <AliasedImageDoubleTags imageFrgmt={row} />,
    },
    {
      title: t('environment.ImageStatus'),
      key: 'status',
      dataIndex: 'status',
      sorter: isEnableSorter('status'),
      render: (value) =>
        value ? (
          <Badge
            variant={badgeVariantForTagColor(
              value === 'ALIVE'
                ? 'green'
                : value === 'DELETED'
                  ? 'red'
                  : 'gold',
            )}
            label={value}
          />
        ) : (
          '-'
        ),
    },
    {
      title: t('data.Type'),
      key: 'type',
      dataIndex: 'type',
      // `type` is in the backend order colmap but points at a column that does
      // not exist on the image row, so ordering by it raises server-side.
      render: (value) => value ?? '-',
    },
    {
      title: t('environment.Local'),
      key: 'is_local',
      dataIndex: 'is_local',
      sorter: isEnableSorter('is_local'),
      render: (value) => <BooleanTag value={value} />,
    },
    {
      title: t('environment.Size'),
      key: 'size_bytes',
      dataIndex: 'size_bytes',
      render: (value) => {
        // `convertToBinaryUnit` throws on anything it cannot parse, which
        // would take the whole table down with it.
        const bytes = _.toNumber(value);
        if (_.isNil(value) || !_.isFinite(bytes)) {
          return '-';
        }
        const size = convertToBinaryUnit(_.toString(bytes), 'auto', 2, true);
        return size ? `${size.numberFixed} ${size.displayUnit}` : '-';
      },
    },
    {
      title: t('environment.Aliases'),
      key: 'aliases',
      dataIndex: 'aliases',
      render: (_text, row) => (
        <BAIBadgeList
          items={_.map(_.compact(row.aliases), (alias) => ({
            key: alias,
            label: alias,
          }))}
        />
      ),
    },
    {
      title: t('environment.SupportedAccelerators'),
      key: 'supported_accelerators',
      dataIndex: 'supported_accelerators',
      // The backend order colmap calls this column `accelerators`.
      sorter: isEnableSorter('accelerators'),
      sortKey: 'accelerators',
      render: (_text, row) =>
        _.isEmpty(row.supported_accelerators)
          ? '-'
          : _.join(_.compact(row.supported_accelerators), ', '),
    },
    {
      title: t('environment.Digest'),
      dataIndex: 'digest',
      key: 'digest',
      render: (_text, row) => (
        // antd `Text ellipsis={{tooltip}} maxWidth 200` -> Astryx Text
        // maxLines (truncate tooltip built in); width lives on the BAIFlex
        // wrapper because Astryx Text has no style/width prop.
        <BAIFlex style={{ maxWidth: 200 }} align="stretch">
          <Text maxLines={1}>{row.digest ?? ''}</Text>
        </BAIFlex>
      ),
    },
    {
      title: t('environment.ResourceLimit'),
      dataIndex: 'resource_limits',
      key: 'resource_limits',
      render: (_text, row) => (
        <BAIFlex direction="row" gap="xxs">
          {row?.resource_limits?.map((resource_limit) => (
            <BAIResourceNumberWithIcon
              key={resource_limit?.key}
              type={resource_limit?.key || ''}
              value={resource_limit?.min || '0'}
              max={resource_limit?.max || 'Infinity'}
            />
          ))}
        </BAIFlex>
      ),
    },
    {
      title: t('general.Control'),
      key: 'control',
      dataIndex: 'control',
      fixed: 'right',
      render: (_text, row) => (
        <BAIFlex
          direction="row"
          align="stretch"
          justify="center"
          gap="xxs"
          onClick={(e) => {
            // To prevent the click event from selecting the row
            e.stopPropagation();
          }}
        >
          {/* PILOT-DECISION: antd text Buttons with token.colorInfo-tinted
              icons -> Astryx ghost IconButtons. IconButton's variant enum is
              closed, so the info-blue icon tint is dropped (P5/P11);
              accessible labels reuse the modal titles they open (P8).
              QA-FINDINGS Q-37 — SUPERSEDED for the colour half. The report
              "/admin/environment 페이지의 control 버튼 색상이 default 입니다"
              is precisely this drop: measured rgb(20,20,20) light /
              rgb(255,255,255) dark against antd's `colorInfo` #028DF2/#0387BF.
              The closed enum still has no colour slot, but `className` does:
              `--color-text-accent` on this route resolves through
              `AstryxAdminTheme` to #028DF2/#0387bf, i.e. `colorInfo` exactly,
              so the class restores the tint without a per-route read. The
              `type="text"` hover wash (`colorBgTextHover` rgba(0,0,0,0.06)) is
              already what Astryx's ghost `:hover` paints, so it is untouched.
              See `packages/backend.ai-ui/src/styles/actionAccent.css`. */}
          <IconButton
            className="bai-action-accent"
            variant="ghost"
            icon={<SquarePenIcon />}
            label={t('environment.ModifyMinimumImageResourceLimit')}
            tooltip={t('environment.ModifyMinimumImageResourceLimit')}
            onClick={() => setManagingResourceLimit(row)}
          />
          <IconButton
            className="bai-action-accent"
            variant="ghost"
            icon={<LayoutGrid size="1em" />}
            label={t('environment.ManageApps')}
            tooltip={t('environment.ManageApps')}
            onClick={() => {
              setManagingApp(row);
            }}
          />
        </BAIFlex>
      ),
    },
  ]);

  const [storedHiddenColumnKeys, setHiddenColumnKeys] =
    useHiddenColumnKeysSetting('ImageList');
  // The setting is only seeded once the user opens the column settings, so an
  // untouched account gets the defaults rather than every column at once.
  const hiddenColumnKeys =
    storedHiddenColumnKeys ?? DEFAULT_HIDDEN_IMAGE_COLUMN_KEYS;

  return (
    <>
      <BAIFlex
        direction="column"
        align="stretch"
        style={{
          flex: 1,
          ...style,
        }}
        gap="sm"
      >
        <BAIFlex justify="between" gap="xs" wrap="wrap">
          <BAIFlex gap="xs" align="center" wrap="wrap">
            {projectSelect}
            <BAIPropertyFilter
              filterProperties={filterOutEmpty([
                {
                  key: 'id',
                  propertyLabel: t('environment.ID'),
                  type: 'string',
                  defaultOperator: '==',
                },
                {
                  key: 'image',
                  propertyLabel: t('environment.Image'),
                  type: 'string',
                },
                {
                  key: 'name',
                  propertyLabel: t('environment.Name'),
                  type: 'string',
                },
                {
                  key: 'registry',
                  propertyLabel: t('environment.Registry'),
                  type: 'string',
                },
                {
                  key: 'architecture',
                  propertyLabel: t('environment.Architecture'),
                  type: 'string',
                  strictSelection: true,
                  defaultOperator: '==',
                  options: [
                    { label: 'x86_64', value: 'x86_64' },
                    { label: 'aarch64', value: 'aarch64' },
                  ],
                },
                {
                  key: 'namespace',
                  propertyLabel: t('environment.Namespace'),
                  type: 'string',
                },
                {
                  key: 'base_image_name',
                  propertyLabel: t('environment.BaseImageName'),
                  type: 'string',
                },
                {
                  key: 'tag',
                  propertyLabel: t('environment.Tags'),
                  type: 'string',
                },
                {
                  key: 'status',
                  propertyLabel: t('environment.ImageStatus'),
                  type: 'string',
                  strictSelection: true,
                  defaultOperator: '==',
                  options: _.map([...ALL_IMAGE_STATUSES], (status) => ({
                    label: status,
                    value: status,
                  })),
                },
                {
                  key: 'type',
                  propertyLabel: t('data.Type'),
                  type: 'string',
                  strictSelection: true,
                  defaultOperator: '==',
                  options: [
                    { label: 'COMPUTE', value: 'COMPUTE' },
                    { label: 'SERVICE', value: 'SERVICE' },
                    { label: 'SYSTEM', value: 'SYSTEM' },
                  ],
                },
                {
                  key: 'is_local',
                  propertyLabel: t('environment.Local'),
                  type: 'boolean',
                },
                {
                  key: 'project',
                  propertyLabel: t('environment.RegistryProject'),
                  type: 'string',
                },
                {
                  key: 'registry_id',
                  propertyLabel: t('environment.RegistryID'),
                  type: 'uuid',
                },
                {
                  key: 'created_at',
                  propertyLabel: t('general.CreatedAt'),
                  type: 'datetime',
                },
                {
                  key: 'accelerators',
                  propertyLabel: t('environment.SupportedAccelerators'),
                  type: 'string',
                },
              ])}
              value={imageFilter || undefined}
              onChange={(value) => {
                setImageFilter(value || '');
                setTablePaginationOption({ current: 1 });
              }}
            />
          </BAIFlex>
          <BAIFlex gap={'xs'}>
            {selectedRows.length > 0 ? (
              <BAISelectionLabel
                count={selectedRows.length}
                onClearSelection={() => setSelectedRows([])}
              />
            ) : null}
            <IconButton
              label={t('button.Refresh')}
              tooltip={t('button.Refresh')}
              icon={<RotateCw size="1em" />}
              isLoading={isPendingRefreshTransition}
              onClick={() => {
                setSelectedRows([]);
                startRefreshTransition(() => updateFetchKey());
              }}
            />
            {/* PILOT-DECISION: the hand-painted primary button
                (style backgroundColor token.colorPrimary) becomes Astryx
                `Button variant="primary"` — the brand accent comes from the
                theme layer, not an inline style (P5). */}
            <Button
              variant="primary"
              icon={<ArrowDownToLine size="1em" />}
              label={t('environment.InstallImage')}
              onClick={() => {
                if (selectedRows.length === 0) {
                  message.error(t('environment.NoImagesAreSelected'));
                  return;
                }
                if (selectedRows.some((image) => !image.installed)) {
                  setIsOpenInstallModal(true);
                  return;
                }
                message.error(t('environment.AlreadyInstalledImage'));
              }}
            />
          </BAIFlex>
        </BAIFlex>
        <BAITable
          scroll={{ x: 'max-content' }}
          resizable
          rowKey="id"
          pagination={{
            total: image_nodes?.count ?? undefined,
            ...tablePaginationOption,
            onChange: (page, pageSize) => {
              setTablePaginationOption({ current: page, pageSize });
            },
            extraContent: (
              <IconButton
                variant="ghost"
                icon={<Settings size="1em" />}
                label={t('table.SettingTable')}
                onClick={() => {
                  toggleColumnSettingModal();
                }}
              />
            ),
          }}
          dataSource={imageData}
          columns={_.filter(
            columns,
            (column) => !_.includes(hiddenColumnKeys, _.toString(column?.key)),
          )}
          loading={
            deferredFetchKey !== fetchKey ||
            deferredQueryVariables !== queryVariables
          }
          order={queryParams.order}
          onChangeOrder={(order) => {
            setQueryParams({
              order: order as
                (typeof availableImageSorterValues)[number] | null,
            });
            setTablePaginationOption({ current: 1 });
          }}
          rowSelection={{
            type: 'checkbox',
            onChange: (_, selectedRows) => {
              setSelectedRows(selectedRows);
            },
            selectedRowKeys: selectedRows.map((row) => row.id) as Key[],
          }}
          onRow={(record) => ({
            onClick: () => {
              // selected or deselect row
              if (selectedRows.find((row) => row.id === record.id)) {
                setSelectedRows((rows) =>
                  rows.filter((row) => row.id !== record.id),
                );
              } else {
                setSelectedRows((rows) => [...rows, record]);
              }
            },
          })}
        />
      </BAIFlex>
      <ManageImageResourceLimitModal
        open={!!managingResourceLimit}
        onRequestClose={(success) => {
          setManagingResourceLimit(null);
          if (success)
            startTransition(() => {
              updateFetchKey();
            });
        }}
        imageFrgmt={managingResourceLimit}
      />
      <ManageAppsModal
        open={!!managingApp}
        onRequestClose={(success) => {
          setManagingApp(null);
          if (success)
            startTransition(() => {
              updateFetchKey();
            });
        }}
        imageFrgmt={managingApp}
      />
      {/* No project is handed down: installing an image enqueues a session,
          and the modal asks for that session's own project and resource group.
          The list's project filter only decides which images are on screen.
          Wrapped in `BAIUnmountAfterClose` so the modal keeps its exit
          animation instead of vanishing instantly, while still fully
          unmounting between opens - which is what resets the project /
          resource-group selectors on every fresh open. */}
      <BAIUnmountAfterClose>
        <ImageInstallModal
          open={isOpenInstallModal}
          onRequestClose={() => {
            setIsOpenInstallModal(false);
          }}
          setInstallingImages={setInstallingImages}
          selectedRows={selectedRows}
        />
      </BAIUnmountAfterClose>
      <TableColumnsSettingModal
        open={visibleColumnSettingModal}
        onRequestClose={(values) => {
          values?.selectedColumnKeys &&
            setHiddenColumnKeys(
              _.difference(
                columns.map((column) => _.toString(column.key)),
                values?.selectedColumnKeys,
              ),
            );
          toggleColumnSettingModal();
        }}
        columns={columns}
        hiddenColumnKeys={hiddenColumnKeys}
      />
    </>
  );
};

export default ImageList;
